    },
    {
      "poi_id": "p136",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà ga cổ có mái che, ngắm kiến trúc xưa mà không ướt một giọt."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Trưa nay ngồi bàn cho đàng hoàng, nem nướng cuốn rau thơm, ngon quá (so tasty)."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dinh III kín gió, đi một vòng nghe chuyện vua chúa ngày xưa, khỏi lo trời mưa."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Tối đến khu phức hợp có mái che, đi dạo trong nhà, xem người ta chơi đêm."
    },
    {
      "poi_id": "p330",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa tối ngồi lại quán ấm cúng, ăn chậm, nghe mưa rơi ngoài cửa kính."
    }
  ]
}
